:root{--kagit:#fbfaf6;--beyaz:#fff;--zemin:#f0eee6;--murekkep:#0d1512;--metin2:#4a5550;--cizgi:#d9d7cc;--cam:#0a6847;--cam-koyu:#0b2b21;--sahne:#061a14;--sahne2:#0e3327;--cizgi-k:#234a3c;
--filiz:#c9ffe2;--acik-k:#c4d6cc;--kiremit:#b8431a;--kiremit-acik:#f8e6dd;--cam-acik:#e0ede5;--dolgu:#d6dbd6;
--fd:"Bricolage Grotesque",system-ui,sans-serif;--fb:"IBM Plex Sans",system-ui,sans-serif;--fm:"IBM Plex Mono",ui-monospace,monospace;--kenar:48px;--yum:cubic-bezier(.2,.7,.2,1)}
*{box-sizing:border-box;margin:0;padding:0}html{scroll-behavior:smooth}
body{font:400 17px/1.55 var(--fb);color:var(--murekkep);background:var(--kagit);-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{color:inherit;text-decoration:none}img{display:block;max-width:100%}ul,ol{list-style:none}button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
.w{max-width:1376px;margin:0 auto;padding:0 var(--kenar)}
.g{display:grid;grid-template-columns:repeat(12,1fr);column-gap:24px}
h1,h2,h3{font-family:var(--fd);font-weight:700;letter-spacing:-.03em;line-height:1.02}
h2{font-size:54px;max-width:15ch}
.et{font:500 12px/1 var(--fm);letter-spacing:.09em;text-transform:uppercase;color:var(--cam);margin-bottom:18px}.et.kir{color:var(--kiremit)}
.lead{font-size:18px;color:var(--metin2);max-width:48ch}
.btn{display:inline-flex;align-items:center;justify-content:center;height:52px;padding:0 24px;border:1.5px solid var(--murekkep);font:600 16px/1 var(--fb);border-radius:6px;white-space:nowrap;transition:transform .18s var(--yum),background .18s}
.btn:hover{transform:translateY(-2px)}
.btn.dolu{background:var(--murekkep);color:#fff}.btn.fil{background:var(--filiz);border-color:var(--filiz);color:var(--sahne)}
.btn.kc{height:42px;padding:0 18px;font-size:15px}
.sec{padding:128px 0 0}.bas{align-items:end}.bas .b1{grid-column:1/8}.bas .b2{grid-column:8/13;padding-bottom:6px}
/* çerçeveler */
.tar{background:var(--beyaz);border:1px solid rgba(13,21,18,.16);border-radius:10px;overflow:hidden;box-shadow:0 24px 48px -28px rgba(6,26,20,.45)}
.tb{height:30px;display:flex;align-items:center;gap:6px;padding:0 12px;background:#eeece4;border-bottom:1px solid var(--cizgi)}
.tb i{width:8px;height:8px;border-radius:50%;background:#c9c6b9}.tb span{font:500 11px/1 var(--fm);color:#6b736e;margin-left:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.vp{overflow:hidden}.vp img{width:100%;height:100%;object-fit:cover;object-position:left top}
.tar.pn .tb{background:#f4f5f3}
.telf{border:6px solid var(--murekkep);border-radius:26px;overflow:hidden;background:#000;box-shadow:0 22px 40px -22px rgba(6,26,20,.6)}
.telf img{width:100%;height:100%;object-fit:cover;object-position:top}
.rz{display:inline-block;font:500 11px/20px var(--fm);font-style:normal;padding:0 8px;height:22px;border:1px solid var(--murekkep);border-radius:3px;white-space:nowrap}
.rz.r0{background:var(--cam-acik);border-color:var(--cam);color:var(--cam)}.rz.r1{background:#fff}.rz.r2{background:var(--cam);border-color:var(--cam);color:#fff}.rz.r3{background:var(--murekkep);color:#fff}
.rz.r9{background:var(--kiremit-acik);border-color:var(--kiremit);color:var(--kiremit)}.rz.r8{border-style:dashed;color:var(--metin2);border-color:#8d958f}
/* duyuru + üst */
.duy{background:var(--filiz);color:var(--sahne);font-size:14px}.duy .w{display:flex;justify-content:center;gap:18px;height:38px;align-items:center}.duy a{font-weight:600;border-bottom:1.5px solid var(--sahne)}
.ust{background:var(--sahne);color:#fff;position:sticky;top:0;z-index:30;border-bottom:1px solid var(--cizgi-k)}
.ust .w{display:flex;align-items:center;height:68px;gap:14px}
.logo img{height:32px}.nav{display:flex;gap:26px;font-size:15px;font-weight:500;flex:1;margin-left:30px;color:var(--acik-k)}.nav a:hover{color:#fff}
.ust .gir{font-size:15px;color:var(--acik-k);margin-right:8px}.btn.bos{border-color:rgba(255,255,255,.55);color:#fff}.btn.duz{border-color:transparent;color:#fff;text-decoration:underline;text-underline-offset:5px;text-decoration-color:var(--filiz);padding:0 12px}
.mnu{display:none}
/* hero */
.hero{background:var(--sahne);color:#fff;padding:56px 0 0;position:relative;overflow:hidden;
 background-image:linear-gradient(var(--cizgi-k) 1px,transparent 1px),linear-gradient(90deg,var(--cizgi-k) 1px,transparent 1px);background-size:96px 96px;background-position:center top}
.hero:before{content:"";position:absolute;inset:0;background:var(--sahne);opacity:.82}
.hero>*{position:relative}
.hero .sol{grid-column:1/6;padding-top:22px}
.hero .et{color:var(--filiz)}
.hero h1{font-size:62px;line-height:.98;letter-spacing:-.04em}.hero h1 em{font-style:normal;color:var(--filiz)}.hero h1 span{white-space:nowrap}
.hero .lead{color:var(--acik-k);margin-top:24px;max-width:40ch}
.cta{display:flex;gap:10px;margin-top:30px;flex-wrap:wrap;align-items:center}
.hero .not{font-size:14px;color:#e0e1ff;margin-top:16px}
.sahne{grid-column:6/13;position:relative;height:590px}
.sahne .s1{position:absolute;right:-70px;top:0;width:700px}.sahne .s1 .vp{height:420px}
.sahne .s2{position:absolute;left:8px;bottom:0;width:480px;border-color:rgba(255,255,255,.2)}.sahne .s2 .vp{height:262px}.sahne .s2 img{width:740px;max-width:none;height:auto;margin:-96px 0 0 -62px}
.sahne .s3{position:absolute;right:26px;bottom:14px;width:176px;height:350px;border-color:#000}
.cip{position:absolute;background:#fff;color:var(--murekkep);border-radius:8px;padding:11px 14px;font-size:13px;line-height:1.35;box-shadow:0 18px 34px -18px rgba(0,0,0,.6);display:grid}
.cip b{font:500 11px/1 var(--fm);letter-spacing:.06em;text-transform:uppercase;color:var(--kiremit);margin-bottom:5px}.cip span{color:var(--metin2)}.cip strong{font:700 22px/1.1 var(--fd);letter-spacing:-.02em;margin-top:4px}
.cip.c1{left:-26px;top:92px}.cip.c2{right:214px;bottom:150px}.cip.c2 b{color:var(--cam)}
.sayi{display:grid;grid-template-columns:repeat(5,1fr);border-top:1px solid var(--cizgi-k);margin-top:44px}
.sayi div{padding:22px 20px 26px;border-left:1px solid var(--cizgi-k)}.sayi div:first-child{border-left:0;padding-left:0}
.sayi b,.rk b{display:block;font:700 42px/1 var(--fd);letter-spacing:-.03em;font-variant-numeric:tabular-nums}.sayi b{color:var(--filiz)}.sayi span{font-size:14px;color:var(--acik-k);display:block;margin-top:8px}
/* dört iş */
.dort{background:var(--beyaz);border-bottom:1px solid var(--cizgi)}.dort .w{display:grid;grid-template-columns:1fr 1.25fr 1fr 1fr}
.d{padding:34px 26px 32px;border-left:1px solid var(--cizgi);display:block;transition:background .2s}.d:first-child{border-left:0;padding-left:0}.d:hover{background:var(--kagit)}
.d span{font:500 12px var(--fm);color:var(--metin2)}.d h3{font-size:28px;margin-top:10px}.d p{font-size:15px;color:var(--metin2);margin-top:10px;max-width:30ch}
.d i{font-style:normal;font-weight:600;font-size:15px;display:inline-block;margin-top:16px;border-bottom:1.5px solid var(--cam)}
.d.one{background:var(--kiremit-acik)}.d.one span,.d.one i{color:var(--kiremit)}.d.one i{border-color:var(--kiremit)}.d.one p{color:#5a3a2c}
/* tema */
.one-tema{display:grid;grid-template-columns:5fr 7fr;background:var(--cam-koyu);color:#fff;border-radius:14px;margin-top:56px;overflow:hidden}
.ot-m{padding:48px 44px}.ot-m .et{color:var(--filiz)}.ot-m h3{font-size:36px;max-width:13ch}.ot-m ul{margin:22px 0 28px;border-top:1px solid var(--cizgi-k)}.ot-m li{padding:10px 0;border-bottom:1px solid var(--cizgi-k);font-size:16px;color:var(--acik-k)}
.ot-m .lnk{display:inline-block;margin-left:18px;font-weight:600;font-size:15px;border-bottom:1.5px solid var(--filiz)}
.ot-g{position:relative;padding:44px 0 0 20px;min-height:500px}.ot-g .tar{width:112%;border-radius:10px 0 0 0;border-color:rgba(255,255,255,.18)}.ot-g .tar .vp{height:430px}
.ot-g .tar.kay img{height:auto;object-fit:fill;width:100%}
.ot-g .telf{position:absolute;left:-28px;bottom:26px;width:168px;height:330px}
.flt{display:flex;gap:8px;flex-wrap:wrap;margin-top:56px;position:sticky;top:68px;z-index:12;background:var(--kagit);padding:14px 0;border-bottom:1.5px solid var(--murekkep)}
.flt button{height:42px;padding:0 16px;border:1px solid var(--cizgi);border-radius:21px;font-weight:500;font-size:15px;background:#fff;transition:all .18s}.flt sup{font:500 11px var(--fm);color:var(--metin2);margin-left:3px}
.flt button.on{background:var(--murekkep);border-color:var(--murekkep);color:#fff}.flt button.on sup{color:var(--filiz)}
.tkg{display:grid;grid-template-columns:repeat(12,1fr);gap:44px 24px;margin-top:36px}
.tk{grid-column:span 4;min-width:0}.tk.gen{grid-column:span 6}.tk[hidden]{display:none}
.tk .gv{display:block;position:relative;padding:0 26px 22px 0}
.tk .tar{box-shadow:0 18px 36px -26px rgba(6,26,20,.5);transition:transform .35s var(--yum)}.tk .tar .vp{aspect-ratio:16/10}
.tk .telf{position:absolute;right:0;bottom:0;width:23%;aspect-ratio:9/18.5;border-width:4px;border-radius:16px;transition:transform .35s var(--yum)}
.tk .gv:hover .tar{transform:translateY(-6px)}.tk .gv:hover .telf{transform:translateY(-12px)}
.tk .ov{position:absolute;left:14px;top:44px;background:var(--murekkep);color:#fff;font-weight:600;font-size:14px;padding:9px 14px;border-radius:5px;opacity:0;transform:translateY(6px);transition:all .25s var(--yum)}.tk .gv:hover .ov{opacity:1;transform:none}
.tk .bl{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;margin-top:14px;padding-right:26px}
.tk h3{font-size:21px;letter-spacing:-.02em}.tk p{font-size:14px;color:var(--metin2);margin-top:4px}.etk{font:500 11px var(--fm);color:var(--kiremit);background:var(--kiremit-acik);padding:2px 6px;border-radius:3px;margin-left:6px}
.tk .dn{font-weight:600;font-size:15px;border-bottom:1.5px solid var(--cam);white-space:nowrap}
.tk.tum{background:var(--zemin);border-radius:12px;padding:30px;display:flex;flex-direction:column;justify-content:flex-end;min-height:240px}.tk.tum b{font:700 44px/1 var(--fd);letter-spacing:-.03em}.tk.tum span{font-size:15px;color:var(--metin2);margin-top:10px;max-width:26ch}.tk.tum i{font-style:normal;font-weight:600;margin-top:18px;border-bottom:1.5px solid var(--cam);align-self:flex-start}
.daha{display:none}.tnot{font-size:13px;color:var(--metin2);margin-top:28px}
/* e-ticaret */
.etc{background:var(--beyaz);margin-top:128px;padding:112px 0 112px;border-top:1px solid var(--cizgi);border-bottom:1px solid var(--cizgi)}
.eg{display:grid;grid-template-columns:240px 1fr;gap:56px;margin-top:64px;align-items:start}
.enav{position:sticky;top:104px;display:grid;border-top:1.5px solid var(--murekkep)}
.enav a{padding:13px 0;border-bottom:1px solid var(--cizgi);font-weight:500;font-size:16px;color:var(--metin2);display:flex;gap:14px;transition:color .2s,padding .25s var(--yum)}.enav a span{font:500 12px/1.9 var(--fm)}
.enav a.on{color:var(--murekkep);font-weight:600;padding-left:12px;box-shadow:inset 3px 0 0 var(--kiremit)}.enav a.on span{color:var(--kiremit)}
.sah{display:grid;grid-template-columns:5fr 8fr;gap:36px;padding:0 0 64px;margin-bottom:64px;border-bottom:1px solid var(--cizgi);align-items:start;scroll-margin-top:110px}
.sah .no{font:500 12px var(--fm);color:var(--kiremit)}.sah h3{font-size:34px;margin-top:8px}.sah p{color:var(--metin2);margin-top:12px;font-size:17px}
.sah ul{margin-top:18px;border-top:1px solid var(--cizgi)}.sah li{padding:9px 0 9px 18px;border-bottom:1px solid var(--cizgi);font-size:15px;position:relative}.sah li:before{content:"";position:absolute;left:0;top:18px;width:8px;height:1.5px;background:var(--kiremit)}
.sah .tar .vp{height:370px}.sah .tar img{width:138%;max-width:none;height:auto}
.pz{margin-top:18px;display:grid;gap:12px}.pz b{display:block;font:500 11px var(--fm);letter-spacing:.06em;text-transform:uppercase;color:var(--cam);margin-bottom:8px}.pz .hz b{color:var(--metin2)}
.pz span{display:inline-block;border:1px solid var(--cam);color:var(--cam);border-radius:4px;padding:3px 9px;font-size:14px;font-weight:600;margin:0 6px 6px 0}.pz .hz span{border:1px dashed #8d958f;color:var(--metin2);font-weight:400}
.ekuc{display:grid;grid-template-columns:1fr 1fr;gap:0 36px}
.sah.kck{display:block;padding-bottom:40px;margin-bottom:40px}.sah.kck h3{font-size:28px}.sah.kck .tar{margin-top:22px}.sah.kck .tar .vp{height:200px}.sah.kck .tar img{width:170%}
.eband{background:var(--kiremit-acik);border-radius:12px;padding:28px 32px;display:flex;justify-content:space-between;align-items:center;gap:32px}.eband p{max-width:56ch;font-size:16px;color:#4b2d20}
/* editör */
.edt{background:var(--sahne);color:#fff;padding:112px 0;overflow:hidden}
.edt .sol{grid-column:1/5}.edt .et{color:var(--filiz)}.edt h2{font-size:46px}
.edt ol{margin:32px 0 32px;border-top:1px solid var(--cizgi-k)}.edt li{display:flex;gap:16px;padding:16px 0;border-bottom:1px solid var(--cizgi-k)}
.edt li span{font:700 22px/1.2 var(--fd);color:var(--filiz);width:22px}.edt li b{font-weight:600;font-size:17px}.edt li p{font-size:15px;color:var(--acik-k);margin-top:3px}
.edt .sag{grid-column:5/13;position:relative;margin-right:-90px}.edt .sag .tar{border-color:rgba(255,255,255,.2)}.edt .sag .vp{height:520px}
.pin{position:absolute;background:var(--filiz);color:var(--sahne);font-weight:600;font-size:13px;padding:7px 12px;border-radius:5px;box-shadow:0 10px 22px -10px rgba(0,0,0,.7)}
.pin:after{content:"";position:absolute;left:14px;bottom:-5px;width:10px;height:10px;background:var(--filiz);transform:rotate(45deg)}
.pin.p1{left:-22px;top:330px}.pin.p2{left:236px;top:462px}.pin.p3{left:690px;top:146px}
/* yönetim */
.yg{display:grid;grid-template-columns:repeat(12,1fr);gap:24px;margin-top:64px}
.yb{background:var(--beyaz);border:1px solid var(--cizgi);border-radius:12px;overflow:hidden;display:flex;flex-direction:column}
.yb .ym{padding:28px 28px 24px}.yb h3{font-size:28px;margin-top:12px}.yb .ym>h3:first-child{margin-top:0}.yb p{font-size:15px;color:var(--metin2);margin-top:10px;max-width:46ch}
.yb .tar{border-radius:10px 0 0 0;border-width:1px 0 0 1px;margin-left:28px;box-shadow:none;margin-top:auto}.yb .tar .vp{height:290px}
.y1{grid-column:1/8}.y2{grid-column:8/13}.y3{grid-column:1/6}.y4{grid-column:6/10;background:var(--cam-koyu);color:#fff;border-color:var(--cam-koyu)}.y5{grid-column:10/13}
.y3 .tar .vp,.y5 .tar .vp{height:200px}.yb .tar img{width:130%;max-width:none;height:auto}.y3 .tar img{width:175%}.y5 .tar img{width:300%}.y4 p{color:var(--acik-k)}
.evr{margin-top:18px;border-top:1px solid var(--cizgi-k)}.evr li{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--cizgi-k);font-size:14px}.evr b{font-weight:500}
.y4 .rz{border-color:var(--filiz);background:transparent;color:var(--filiz)}.y4 .rz.r3{background:#fff;color:var(--murekkep);border-color:#fff}.y4 .rz.r8{border-style:dashed;color:var(--acik-k);border-color:var(--acik-k)}
/* paketler */
.pak{background:var(--zemin);margin-top:128px;padding:112px 0}
.sw-k{display:flex;justify-content:flex-end}.sw{display:flex;border:1.5px solid var(--murekkep);border-radius:6px;font:600 15px/1 var(--fb);background:#fff;overflow:hidden}
.sw span{padding:13px 20px}.sw .sec2{background:var(--murekkep);color:#fff}.sw small{font:500 11px var(--fm);color:var(--cam);margin-left:6px}
.pks{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:56px;align-items:stretch}
.pk{background:#fff;border:1px solid var(--cizgi);border-radius:12px;padding:28px 26px;display:flex;flex-direction:column}
.pk.one{background:var(--cam-koyu);color:#fff;border-color:var(--cam-koyu);margin:-14px 0;padding-top:42px;padding-bottom:42px}
.ph{display:flex;justify-content:space-between;align-items:baseline}.ph span{font:500 12px var(--fm);color:var(--metin2)}.pk h3{font-size:28px}
.pk .kim{font-size:15px;color:var(--metin2);margin-top:10px;min-height:68px}.pk.one .kim,.pk.one .yil,.pk.one .fy span,.pk.one .ph span{color:var(--acik-k)}
.fy{margin-top:14px;display:flex;align-items:baseline;gap:8px}.fy b{font:700 52px/1 var(--fd);letter-spacing:-.04em;font-variant-numeric:tabular-nums}.fy span{font-size:14px;color:var(--metin2)}
.pk .yil{font-size:14px;color:var(--metin2);margin-top:6px}
.pk ul{margin:20px 0 24px;border-top:1px solid var(--cizgi);flex:1}.pk li{padding:9px 0;border-bottom:1px solid var(--cizgi);font-size:15px}.pk li:first-child{font-weight:600}.pk.one ul,.pk.one li{border-color:var(--cizgi-k)}
.pk .btn{height:48px}.pk.one .btn{background:var(--filiz);color:var(--sahne);border-color:var(--filiz)}
.ekm{margin-top:30px;background:#fff;border:1.5px solid var(--kiremit);border-radius:12px;padding:24px 28px;display:grid;grid-template-columns:220px 1fr auto;gap:28px;align-items:center}
.ekm .et{margin-bottom:8px}.ekm h3{font-size:30px}.ekm p{font-size:16px;color:var(--metin2);max-width:60ch}
.yt{font:500 12px/1.5 var(--fm);color:var(--metin2);margin-top:14px}
table{width:100%;border-collapse:separate;border-spacing:0;margin-top:56px;background:#fff;border:1px solid var(--cizgi);border-radius:12px;table-layout:fixed;overflow:hidden}
thead th{font:700 18px/1 var(--fd);letter-spacing:-.02em;padding:20px 8px;text-align:center;border-bottom:1.5px solid var(--murekkep);position:sticky;top:68px;background:#fff;z-index:5}
thead th:first-child{text-align:left;padding-left:24px;width:52%;font:500 12px var(--fm);letter-spacing:.08em;text-transform:uppercase;color:var(--metin2)}thead th .k{display:none}
tr.grp th{text-align:left;padding:24px 24px 9px;font:500 12px/1 var(--fm);letter-spacing:.08em;text-transform:uppercase;color:var(--cam);border-top:1px solid var(--cizgi)}
